#pragma once
/* Bitmap font for the burned-in OSD (generated by gen_font.py). */
typedef struct {
    int w, h;                    /* cell size in pixels (monospace advance = w) */
    int bytes_per_glyph;         /* 2 bits per pixel, 4 pixels per byte */
    const unsigned char *bits;   /* glyphs 0x20..0x7e, in order */
} osd_font_t;

/* 1x and 2x sizes for the 1920x1080 main and the 640x360 sub stream */
extern const osd_font_t osd_font_main1, osd_font_main2;
extern const osd_font_t osd_font_sub1, osd_font_sub2;

/* 0 empty, 1 edge, 2 solid. Characters outside 0x20..0x7e draw as '?'. */
static inline int osd_font_px(const osd_font_t *f, unsigned char c, int x, int y)
{
    if (c < 0x20 || c > 0x7e) c = '?';
    int i = y * f->w + x;
    return (f->bits[(c - 0x20) * f->bytes_per_glyph + (i >> 2)] >> ((i & 3) * 2)) & 3;
}
